import{z as s,x as i,o as A,c as d,q as l,j as o,D as E,d as r,s as n,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"变长记录与溢出页","description":"","frontmatter":{"title":"变长记录与溢出页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/varlen-overflow.md","filePath":"cs/varlen-overflow.md","lastUpdated":1791063341000}'),p={name:"cs/varlen-overflow.md"};function D(C,a,m,c,u,f){const B=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=l('<h1 id="变长记录与溢出页" tabindex="-1">变长记录与溢出页 <a class="header-anchor" href="#变长记录与溢出页" aria-label="Permalink to &quot;变长记录与溢出页&quot;">​</a></h1><div class="epigraph"><p>槽化页假定记录进一页；变长列一涨，行要拆成页内头与溢出页链，RID 仍指头，扫描变成追逐。</p><footer>—— 据 Ramakrishnan and Gehrke 页与槽；Gray and Reuter；主干 page-slot 的溢出补全</footer></div><p><a href="/cs/learned-index">上一课</a>在有序键上赌模型。本课不拟合 CDF。缺口是行存物理：主干 <a href="/cs/page-slot">页与槽</a> 给定长直觉；真实 <code>VARCHAR</code>/<code>JSONB</code> 变长，更新变长导致页满、行迁移、溢出页（overflow / TOAST 一类）。延迟物化与覆盖索引都假设 RID 仍能找到载荷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>插入变长行：页空闲不够则新页或压缩空洞。更新变长：行变大可能迁到另一页，旧槽留转发地址（forwarding RID），索引可仍指旧 RID，避免全改二级索引。极大字段：页内只留指针，数据在溢出页或侧表。缺口是<strong>访问路径变间接</strong>，I/O 从一次变多次，代价模型要计。</p><p>碎片：频繁变长更新留下不可用小洞，需要页内整理或 vacuum。与 pin-latch：迁移时持写闩，读者要跟转发。</p><p><span class="marginnote">PostgreSQL TOAST、InnoDB 溢出页是产品名。本课机制：行头+溢出链。本课不把大对象 API 写完——下一课 BLOB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>页格式：槽指向行头；行头含标志「有溢出」。扫描：跟指针读列。压缩行（前缀压缩）是另一减少溢出的手段。最大行限制：超过则强制溢出或拒绝。</p><p>索引：键通常截断或哈希前缀，完整键在堆行。比较长键可能要取溢出——执行器注意。</p>',10)),(A(),o(t,null,{default:E(()=>[n(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RID%5B%22RID%20%E6%A7%BD%22%5D%20--%3E%20HEAD%5B%22%E9%A1%B5%E5%86%85%E8%A1%8C%E5%A4%B4%22%5D%0A%20%20HEAD%20--%3E%20IN%5B%22%E9%A1%B5%E5%86%85%E5%88%97%22%5D%0A%20%20HEAD%20--%3E%20OV%5B%22%E6%BA%A2%E5%87%BA%E9%A1%B5%E9%93%BE%22%5D%0A%20%20UPD%5B%22%E8%A1%8C%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%20RID%20%E6%88%96%E6%96%B0%E6%A7%BD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"WAL：溢出页与主页都要记生理日志，恢复顺序按 LSN。延迟物化：先读行头谓词列，谓词列若在溢出则迟物化失败变早读。列存较少「一行跨页」，但超长字符串仍有字典块。",-1)),a[5]||(a[5]=e("p",null,"缓冲：溢出页易成一次性，2Q 应快速逐出，避免污染。",-1)),a[6]||(a[6]=e("p",null,"一次二级索引点查在「转发 + 溢出」叠加时的真实 I/O 路径——间接跳如何层层加码：",-1)),(A(),o(t,null,{default:E(()=>[n(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDX%5B%22%E4%BA%8C%E7%BA%A7%E7%B4%A2%E5%BC%95%E9%A1%B9%20%E2%86%92%20%E6%97%A7%20RID%22%5D%20--%3E%20P1%5B%22%E8%AF%BB%E4%B8%BB%E9%A1%B5%201%3A%20%E6%97%A7%E6%A7%BD%22%5D%0A%20%20P1%20--%3E%20Q%7B%22%E6%A7%BD%E6%98%AF%E8%BD%AC%E5%8F%91%20RID%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%90%A6%2C%20%E8%A1%8C%E5%9C%A8%E5%8E%9F%E5%9C%B0%7C%20V1%5B%22%E8%BF%94%E5%9B%9E%E8%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20P2%5B%22%E8%AF%BB%E4%B8%BB%E9%A1%B5%202%3A%20%E6%96%B0%E6%A7%BD%22%5D%0A%20%20P2%20--%3E%20Q2%7B%22%E8%A1%8C%E5%A4%B4%E6%A0%87%E6%BA%A2%E5%87%BA%3F%22%7D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20V2%5B%22%E8%BF%94%E5%9B%9E%E8%A1%8C%2C%20%E5%85%B1%202%20%E6%AC%A1%20I%2FO%22%5D%0A%20%20Q2%20--%3E%7C%E6%98%AF%2C%20%E8%B6%85%E9%95%BF%E5%88%97%E5%9C%A8%E9%93%BE%E4%B8%8A%7C%20OV1%5B%22%E8%AF%BB%E6%BA%A2%E5%87%BA%E9%A1%B5%201%22%5D%0A%20%20OV1%20--%3E%20OV2%5B%22%E8%AF%BB%E6%BA%A2%E5%87%BA%E9%A1%B5%202%20...%20%E6%B2%BF%E9%93%BE%E8%BF%BD%E9%80%90%22%5D%0A%20%20OV2%20--%3E%20VF%5B%22%E5%88%97%E9%BD%90%E4%BA%86%E6%89%8D%E8%BF%94%E5%9B%9E%2C%20I%2FO%20%E2%89%A5%204%20%E6%AC%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：按 4 KB 页算，一行 <code>VARCHAR</code> 从 200 B 更新到 5 KB 时，旧页塞不下——典型实现（如 TOAST 阈值约四分之一页）会把超长列拆出侧表，页内行头只留 18 B 左右的指针。此后每次读该列，I/O 从 1 页变 2 页起，转发再各加一跳。</span></p><p><span class="marginnote">转发 RID 可以想象成「旧门上贴的搬家便条」：二级索引还写着旧地址，一敲门，便条指去新家。好处是几十个索引一个都不用改；代价是此后每一次点查都多付一跳 I/O，直到 vacuum 或页整理把索引批量改写干净。</span></p><p><span class="marginnote">常见误区：以为二级索引里存着完整的键值就行、与行在哪无关。长键（比如整段 URL）常被截断或取前缀放进索引项，比较相等够了，取回整行仍要沿 RID 追——若谓词列恰好在溢出链上，「延迟物化」的省 I/O 收益会反转为提前多次读。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 BLOB 流式 API 与外部文件。也不把宽列单元格当溢出链。表分区是水平切，溢出是垂直拆行。</p><p>后课默认：变长更新可能转发与溢出，点查 I/O 不只一页。大对象存储：专门的大值路径，避免普通行槽被单列撑爆。</p><p>转发保持二级索引稳定，代价是每次多一次跳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>变长行用槽+可选溢出链；更新可转发 RID。</li><li>代价与 WAL 必须看见间接跳。</li><li>大对象存储下一课：超大值不走普通槽。</li><li>出处：Ramakrishnan and Gehrke；Gray and Reuter；TOAST/溢出实践。</li></ul>',9))])}const F=s(p,[["render",D]]);export{I as __pageData,F as default};
